"""Front3D-specific layout loading, encoding, and voxelization."""

import os
from collections import deque
from typing import Dict, List, Tuple

try:
    import h5py
except ImportError:  # optional; only needed to LOAD .h5 layouts
    h5py = None
import numpy as np
import torch

from .map_utils import FEATURE_DIM, rasterize_oriented_boxes, rasterize_polylines


FRONT3D_NUM_SUBTYPE_CHANNELS = 10

FRONT3D_FEATURE_TYPE_TO_INDEX = {
    "floor_layout": 0,
    "wall_inner": 1,
    "wall_outer": 2,
    "door": 3,
    "window": 4,
    "furniture": 5,
}

FRONT3D_LAYOUT_TYPE_TO_FEATURE_INDEX = {
    0: FRONT3D_FEATURE_TYPE_TO_INDEX["wall_inner"],
    1: FRONT3D_FEATURE_TYPE_TO_INDEX["wall_outer"],
    2: FRONT3D_FEATURE_TYPE_TO_INDEX["door"],
    3: FRONT3D_FEATURE_TYPE_TO_INDEX["window"],
}

FRONT3D_CATEGORY_TO_SUBTYPE = {
    "chair": 0,
    "table": 1,
    "bed": 2,
    "sofa": 3,
    "cabinet": 4,
    "storage unit": 5,
    "lighting": 6,
    "media unit": 7,
    "plants": 8,
}


def _category_to_subtype_index(raw_category: str) -> int:
    label = raw_category.strip().lower()
    prefix = label.split("/")[0].strip()
    if prefix in FRONT3D_CATEGORY_TO_SUBTYPE:
        return FRONT3D_CATEGORY_TO_SUBTYPE[prefix]

    keyword_groups = [
        ("chair", ["chair", "stool", "bench", "ottoman", "beanbag", "pier stool"]),
        ("table", ["table", "desk", "nightstand", "stand"]),
        ("bed", ["bed", "mattress", "bunk", "crib"]),
        ("sofa", ["sofa", "couch", "loveseat", "sectional"]),
        ("cabinet", ["cabinet", "wardrobe", "dresser", "drawer", "sideboard", "cupboard"]),
        ("storage unit", ["shelf", "bookshelf", "bookcase", "storage", "rack", "closet"]),
        ("lighting", ["lamp", "light", "chandelier", "lantern"]),
        ("media unit", ["tv", "television", "monitor", "media", "console"]),
        ("plants", ["plant", "flower", "vase", "tree", "bonsai"]),
    ]
    for subtype, keywords in keyword_groups:
        if any(keyword in label for keyword in keywords):
            return FRONT3D_CATEGORY_TO_SUBTYPE[subtype]
    return FRONT3D_CATEGORY_TO_SUBTYPE.get(prefix, 9)


def _encode_wall_segment(p1: np.ndarray, p2: np.ndarray, wall_type_index: int, polyline_id: int) -> np.ndarray:
    features = np.zeros((2, FEATURE_DIM), dtype=np.float32)
    features[0, 0] = p1[0]
    features[0, 2] = p1[1]
    features[1, 0] = p2[0]
    features[1, 2] = p2[1]
    features[:, 9 + wall_type_index] = 1.0
    features[:, 34] = float(polyline_id)
    return features


def _clip_segment_to_chunk(
    p1: np.ndarray,
    p2: np.ndarray,
    x_min: float,
    x_max: float,
    y_min: float,
    y_max: float,
) -> Tuple[np.ndarray, np.ndarray] | None:
    """Clip a 2D segment to an axis-aligned chunk rectangle using Liang-Barsky."""
    x1, y1 = float(p1[0]), float(p1[1])
    x2, y2 = float(p2[0]), float(p2[1])
    dx = x2 - x1
    dy = y2 - y1

    p = (-dx, dx, -dy, dy)
    q = (x1 - x_min, x_max - x1, y1 - y_min, y_max - y1)

    u0, u1 = 0.0, 1.0
    for pi, qi in zip(p, q):
        if abs(pi) < 1e-8:
            if qi < 0:
                return None
            continue
        t = qi / pi
        if pi < 0:
            u0 = max(u0, t)
        else:
            u1 = min(u1, t)
        if u0 > u1:
            return None

    cp1 = np.array([x1 + u0 * dx, y1 + u0 * dy], dtype=np.float32)
    cp2 = np.array([x1 + u1 * dx, y1 + u1 * dy], dtype=np.float32)
    return cp1, cp2


def _encode_room_centroid(centroid_xz: np.ndarray) -> np.ndarray:
    features = np.zeros((1, FEATURE_DIM), dtype=np.float32)
    features[0, 0] = centroid_xz[0]
    features[0, 2] = centroid_xz[1]
    features[0, 9 + FRONT3D_FEATURE_TYPE_TO_INDEX["floor_layout"]] = 1.0
    return features


def _encode_furniture_bbox(center_xzy: np.ndarray, half_extents_xzy: np.ndarray, subtype_index: int) -> np.ndarray:
    features = np.zeros((1, FEATURE_DIM), dtype=np.float32)
    features[0, 0:3] = center_xzy
    features[0, 3:6] = half_extents_xzy
    features[0, 6] = 1.0
    features[0, 8] = 1.0
    features[0, 9 + FRONT3D_FEATURE_TYPE_TO_INDEX["furniture"]] = 1.0
    features[0, 15 + subtype_index] = 1.0
    return features


def load_front3d_layout(layout_path: str, bbox_path: str) -> Dict:
    data = {}
    with h5py.File(layout_path, "r") as f:
        data["wall_segments"] = f["wall_segments"][:]
        data["wall_types"] = f["wall_types"][:].astype(np.int8)
        data["polyline_ids"] = f["polyline_ids"][:]
        data["room_centroids"] = f["room_centroids"][:]
        data["scene_min"] = f["scene_min"][:]
        data["scene_max"] = f["scene_max"][:]

    if bbox_path is not None and os.path.exists(bbox_path):
        with h5py.File(bbox_path, "r") as f:
            data["furniture_bboxes"] = f["bbox"][:]
            data["furniture_categories"] = [c.decode() for c in f["category"][:]]
    else:
        data["furniture_bboxes"] = np.zeros((0, 2, 3), dtype=np.float32)
        data["furniture_categories"] = []
    return data


def get_local_front3d_features(
    layout_data: Dict,
    scene_shape: Tuple[int, int, int],
    bbox_min: np.ndarray,
    bbox_max: np.ndarray,
) -> np.ndarray:
    # Raw Front3D volumes on disk are [Z_floor, Y_height, X_floor].
    # Exported layout geometry is normalized in world-floor coordinates [x, z].
    # We encode local layout features into the same tensor convention used by
    # the training topdown views: [row=Z_floor, height=Y_height, col=X_floor].
    scene_z, scene_h, scene_x = scene_shape
    all_features = []

    wall_segments = layout_data["wall_segments"]
    wall_types = layout_data["wall_types"]
    polyline_ids = layout_data["polyline_ids"]

    if len(wall_segments) > 0:
        segs_vox = wall_segments.copy()
        x_vox = segs_vox[:, :, 0] * scene_x
        z_vox = segs_vox[:, :, 1] * scene_z

        chunk_z_min, chunk_z_max = float(bbox_min[0]), float(bbox_max[0])
        chunk_x_min, chunk_x_max = float(bbox_min[2]), float(bbox_max[2])

        for x_seg, z_seg, wtype, pid in zip(x_vox, z_vox, wall_types, polyline_ids):
            # Clip in [row=z, col=x] space to the sampled chunk rectangle.
            p1 = np.array([z_seg[0], x_seg[0]], dtype=np.float32)
            p2 = np.array([z_seg[1], x_seg[1]], dtype=np.float32)
            clipped = _clip_segment_to_chunk(p1, p2, chunk_z_min, chunk_z_max, chunk_x_min, chunk_x_max)
            if clipped is None:
                continue
            p1_clip_rc, p2_clip_rc = clipped

            lp1 = np.array([p1_clip_rc[0] - chunk_z_min, p1_clip_rc[1] - chunk_x_min], dtype=np.float32)
            lp2 = np.array([p2_clip_rc[0] - chunk_z_min, p2_clip_rc[1] - chunk_x_min], dtype=np.float32)
            feature_type_index = FRONT3D_LAYOUT_TYPE_TO_FEATURE_INDEX.get(int(wtype))
            if feature_type_index is None:
                continue
            all_features.append(_encode_wall_segment(lp1, lp2, feature_type_index, int(pid)))

    room_centroids = layout_data["room_centroids"]
    if len(room_centroids) > 0:
        cents_vox = room_centroids.copy()
        cents_vox[:, 0] *= scene_x
        cents_vox[:, 1] *= scene_z
        chunk_z_min, chunk_z_max = float(bbox_min[0]), float(bbox_max[0])
        chunk_x_min, chunk_x_max = float(bbox_min[2]), float(bbox_max[2])
        for cx, cz in cents_vox:
            if chunk_x_min <= cx <= chunk_x_max and chunk_z_min <= cz <= chunk_z_max:
                all_features.append(_encode_room_centroid(np.array([cz - chunk_z_min, cx - chunk_x_min], dtype=np.float32)))

    furniture_bboxes = layout_data["furniture_bboxes"]
    furniture_categories = layout_data["furniture_categories"]
    if len(furniture_bboxes) > 0:
        bboxes_vox = furniture_bboxes.copy()
        # Stored bbox order is [x, y, z]; raw volume order is [z, y, x].
        bboxes_vox[:, :, 0] *= scene_x
        bboxes_vox[:, :, 1] *= scene_h
        bboxes_vox[:, :, 2] *= scene_z

        chunk_z_min, chunk_z_max = float(bbox_min[0]), float(bbox_max[0])
        chunk_h_min, chunk_h_max = float(bbox_min[1]), float(bbox_max[1])
        chunk_x_min, chunk_x_max = float(bbox_min[2]), float(bbox_max[2])

        for bbox, cat in zip(bboxes_vox, furniture_categories):
            box_min, box_max = bbox[0], bbox[1]  # [x, y, z]
            bx_min, by_min, bz_min = box_min
            bx_max, by_max, bz_max = box_max
            if bz_max < chunk_z_min or bz_min > chunk_z_max:
                continue
            if by_max < chunk_h_min or by_min > chunk_h_max:
                continue
            if bx_max < chunk_x_min or bx_min > chunk_x_max:
                continue

            cz = (bz_min + bz_max) / 2.0
            cy = (by_min + by_max) / 2.0
            cx = (bx_min + bx_max) / 2.0
            hz = (bz_max - bz_min) / 2.0
            hh = (by_max - by_min) / 2.0
            hx = (bx_max - bx_min) / 2.0

            center_xzy = np.array([cz - chunk_z_min, cy - chunk_h_min, cx - chunk_x_min], dtype=np.float32)
            # Generic box encoding in our tensor convention [row, height, col]:
            # [3] extent along row (z), [4] extent along col (x), [5] extent along height (y).
            half_extents_xzy = np.array([hz, hx, hh], dtype=np.float32)
            all_features.append(_encode_furniture_bbox(center_xzy, half_extents_xzy, _category_to_subtype_index(cat)))

    if not all_features:
        return np.zeros((0, FEATURE_DIM), dtype=np.float32)
    return np.concatenate(all_features, axis=0)


def _collect_polylines_from_mask(positions: torch.Tensor, polyline_ids: torch.Tensor, type_mask: torch.Tensor) -> List[torch.Tensor]:
    if not type_mask.any():
        return []
    type_positions = positions[type_mask].clone()
    type_positions[:, 1] = 0
    type_pids = polyline_ids[type_mask]
    polylines = []
    for pid in torch.unique(type_pids):
        if pid == 0:
            continue
        pts = type_positions[type_pids == pid]
        if len(pts) > 1:
            polylines.append(pts)
    return polylines


def _rasterize_structure_mask_2d(
    positions: torch.Tensor,
    polyline_ids: torch.Tensor,
    type_mask: torch.Tensor,
    flat_shape: Tuple[int, int, int],
    device: str,
) -> torch.Tensor:
    polylines = _collect_polylines_from_mask(positions, polyline_ids, type_mask)
    if not polylines:
        return torch.zeros((flat_shape[0], flat_shape[2]), dtype=torch.float32, device=device)
    return rasterize_polylines(polylines, flat_shape, device)[:, 0, :]


def _flood_fill_floor(wall_grid: np.ndarray, seed_positions: np.ndarray, X: int, Y: int) -> np.ndarray:
    filled = np.zeros((X, Y), dtype=np.float32)
    visited = np.zeros((X, Y), dtype=bool)
    visited[wall_grid > 0.5] = True

    for seed in seed_positions:
        sx = int(round(float(seed[0])))
        sy = int(round(float(seed[2])))
        if sx < 0 or sx >= X or sy < 0 or sy >= Y or visited[sx, sy]:
            continue
        queue = deque([(sx, sy)])
        visited[sx, sy] = True
        while queue:
            cx, cy = queue.popleft()
            filled[cx, cy] = 1.0
            for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < X and 0 <= ny < Y and not visited[nx, ny]:
                    visited[nx, ny] = True
                    queue.append((nx, ny))
    return filled


def vector_to_voxel_map_front3d(
    vectorized_map: torch.Tensor,
    output_size: Tuple[int, int, int],
    factor: int,
    layout_config,
    voxel_size: float,
    device: str = "cpu",
) -> torch.Tensor:
    latent_size = tuple(s // factor for s in output_size)
    num_channels = len(layout_config.types) + (FRONT3D_NUM_SUBTYPE_CHANNELS if layout_config.include_subtypes else 0)

    if vectorized_map.shape[0] == 0:
        return torch.zeros((num_channels, *latent_size), dtype=torch.float32, device=device)

    if vectorized_map.device != torch.device(device):
        vectorized_map = vectorized_map.to(device)

    positions = vectorized_map[:, :3].clone() / factor
    type_onehot = vectorized_map[:, 9:15]
    subtype_onehot = vectorized_map[:, 15:25]
    polyline_ids = vectorized_map[:, 34]

    if not layout_config.preserve_height:
        rasterize_shape = (latent_size[0], 1, latent_size[2])
        positions[:, 1] = 0
    else:
        rasterize_shape = latent_size
    flat_shape = (rasterize_shape[0], 1, rasterize_shape[2])
    result = torch.zeros((num_channels,) + rasterize_shape, dtype=torch.float32, device=device)
    channel_idx = 0

    floor_seed_mask = type_onehot[:, FRONT3D_FEATURE_TYPE_TO_INDEX["floor_layout"]] > 0.5
    wall_inner_mask = type_onehot[:, FRONT3D_FEATURE_TYPE_TO_INDEX["wall_inner"]] > 0.5
    wall_outer_mask = type_onehot[:, FRONT3D_FEATURE_TYPE_TO_INDEX["wall_outer"]] > 0.5
    door_mask = type_onehot[:, FRONT3D_FEATURE_TYPE_TO_INDEX["door"]] > 0.5
    window_mask = type_onehot[:, FRONT3D_FEATURE_TYPE_TO_INDEX["window"]] > 0.5

    wall_inner_2d = _rasterize_structure_mask_2d(positions, polyline_ids, wall_inner_mask, flat_shape, device)
    wall_outer_2d = _rasterize_structure_mask_2d(positions, polyline_ids, wall_outer_mask, flat_shape, device)
    door_2d = _rasterize_structure_mask_2d(positions, polyline_ids, door_mask, flat_shape, device)
    window_2d = _rasterize_structure_mask_2d(positions, polyline_ids, window_mask, flat_shape, device)
    opening_2d = torch.maximum(door_2d, window_2d)
    wall_2d = torch.maximum(wall_inner_2d, wall_outer_2d)

    if floor_seed_mask.any() and (wall_inner_2d.any() or wall_outer_2d.any()):
        seed_positions = positions[floor_seed_mask]
        inside_outer_np = _flood_fill_floor(torch.maximum(wall_outer_2d, opening_2d).cpu().numpy(), seed_positions.cpu().numpy(), flat_shape[0], flat_shape[2])
        inside_inner_np = _flood_fill_floor(torch.maximum(wall_inner_2d, opening_2d).cpu().numpy(), seed_positions.cpu().numpy(), flat_shape[0], flat_shape[2])
        wall_band_np = np.logical_and(inside_outer_np > 0.5, inside_inner_np < 0.5).astype(np.float32)
        wall_2d = torch.maximum(wall_2d, torch.from_numpy(wall_band_np).to(device))
    if opening_2d.any():
        wall_2d = wall_2d * (opening_2d <= 0.5).float()

    for map_type in layout_config.types:
        if map_type == "floor_layout":
            floor_2d = torch.zeros((rasterize_shape[0], rasterize_shape[2]), dtype=torch.float32, device=device)
            wall_barrier_2d = torch.maximum(wall_2d, opening_2d)
            if floor_seed_mask.any() and wall_barrier_2d.any():
                floor_2d = torch.from_numpy(
                    _flood_fill_floor(wall_barrier_2d.cpu().numpy(), positions[floor_seed_mask].cpu().numpy(), rasterize_shape[0], rasterize_shape[2])
                ).float().to(device)
            result[channel_idx] = floor_2d.unsqueeze(1).repeat_interleave(rasterize_shape[1], dim=1)
        elif map_type == "wall":
            result[channel_idx] = wall_2d.unsqueeze(1).repeat_interleave(rasterize_shape[1], dim=1)
        elif map_type == "door":
            result[channel_idx] = door_2d.unsqueeze(1).repeat_interleave(rasterize_shape[1], dim=1)
        elif map_type == "window":
            result[channel_idx] = window_2d.unsqueeze(1).repeat_interleave(rasterize_shape[1], dim=1)
        elif map_type == "furniture":
            furn_mask = type_onehot[:, FRONT3D_FEATURE_TYPE_TO_INDEX["furniture"]] > 0.5
            if furn_mask.any():
                boxes = []
                for pos, he in zip(positions[furn_mask], vectorized_map[furn_mask, 3:6]):
                    boxes.append({
                        "center": pos,
                        "heading": 0.0,
                        "length": (he[0] * 2.0 * voxel_size / factor).item(),
                        "width": (he[1] * 2.0 * voxel_size / factor).item(),
                        "height": (he[2] * 2.0 * voxel_size / factor).item(),
                    })
                if boxes:
                    result[channel_idx] = rasterize_oriented_boxes(boxes, rasterize_shape, voxel_size, device)
        channel_idx += 1

    if layout_config.include_subtypes:
        furn_mask = type_onehot[:, FRONT3D_FEATURE_TYPE_TO_INDEX["furniture"]] > 0.5
        furn_positions = positions[furn_mask]
        furn_half_extents = vectorized_map[furn_mask, 3:6]
        furn_subtypes = subtype_onehot[furn_mask]
        for cat_idx in range(FRONT3D_NUM_SUBTYPE_CHANNELS):
            cat_mask = furn_subtypes[:, cat_idx] > 0.5 if furn_mask.any() else torch.zeros(0, dtype=torch.bool)
            if cat_mask.any():
                boxes = []
                for pos, he in zip(furn_positions[cat_mask], furn_half_extents[cat_mask]):
                    boxes.append({
                        "center": pos,
                        "heading": 0.0,
                        "length": (he[0] * 2.0 * voxel_size / factor).item(),
                        "width": (he[1] * 2.0 * voxel_size / factor).item(),
                        "height": (he[2] * 2.0 * voxel_size / factor).item(),
                    })
                if boxes:
                    result[channel_idx] = rasterize_oriented_boxes(boxes, rasterize_shape, voxel_size, device)
            channel_idx += 1

    if not layout_config.preserve_height:
        # Result layout is [C, X, Z, Y]; when we rasterize in 2D we keep Z=1
        # and need to broadcast along that height axis, not along X.
        result = result.repeat_interleave(latent_size[1], dim=2)
    return result.float()
